"""Reference-style helper glyphs and their physical frame alignment."""
import json
from model_interaction import rendered_frame

FIXTURE = '''<robot name="helper_fixture">
<link name="base"><inertial><origin xyz=".04 -.025 .7" rpy=".2 .3 -.1"/><mass value="1"/><inertia ixx=".01" iyy=".018" izz=".022" ixy=".002" ixz="-.001" iyz=".003"/></inertial><visual><origin xyz="0 0 .7"/><geometry><box size=".5 .3 .3"/></geometry><material name="opaque"><color rgba=".8 .8 .8 1"/></material></visual></link>
<link name="arm"><inertial><origin xyz=".21 .015 -.02" rpy="-.1 .25 .4"/><mass value=".6"/><inertia ixx=".01" iyy=".01" izz=".01"/></inertial><visual><origin xyz=".25 0 0"/><geometry><box size=".5 .12 .12"/></geometry><material name="glass"><color rgba=".8 .8 .8 .65"/></material></visual></link>
<link name="slider"><inertial><origin xyz="0 0 -.18"/><mass value=".3"/><inertia ixx=".01" iyy=".01" izz=".01"/></inertial><visual><origin xyz="0 0 -.2"/><geometry><box size=".1 .1 .4"/></geometry></visual></link>
<joint name="rotate" type="revolute"><origin xyz=".3 0 .7" rpy=".2 -.3 .4"/><parent link="base"/><child link="arm"/><axis xyz=".2 .7 .4"/><limit lower="-1" upper="1" effort="10" velocity="2"/></joint>
<joint name="slide" type="prismatic"><origin xyz="-.3 0 .7" rpy="-.2 .1 -.4"/><parent link="base"/><child link="slider"/><axis xyz=".1 .2 1"/><limit lower="0" upper=".3" effort="10" velocity="2"/></joint>
</robot>'''


def check_helper_visuals(client, output, check):
    client.js('document.getElementById("source").value='+json.dumps(FIXTURE)+';document.getElementById("source").dispatchEvent(new Event("input"));document.getElementById("reload").click()')
    client.until('urdfWorkbench.viewer.robot?.robotName==="helper_fixture"&&!urdfWorkbench.loading')
    for key in ['inertia', 'com', 'axes', 'jointAxes']:
        client.js('if(!urdfWorkbench.display['+json.dumps(key)+'])document.querySelector('+json.dumps(f'[data-display={key}]')+').click()')
    rendered_frame(client)
    client.js('window.helperTestThree=parcelRequire("../node_modules/three/build/three.module.js")')
    alignment = '''(()=>{const T=helperTestThree,v=urdfWorkbench.viewer;v.world.updateWorldMatrix(true,true);const origins={base:[[.04,-.025,.7],[.2,.3,-.1]],arm:[[.21,.015,-.02],[-.1,.25,.4]],slider:[[0,0,-.18],[0,0,0]]};return Object.entries(v.robot.links).every(([name,link])=>{const marker=link.children.find(c=>c.userData.markerKind==='com');if(!marker)return false;const [xyz,rpy]=origins[name],expected=link.localToWorld(new T.Vector3(...xyz));const qx=new T.Quaternion().setFromAxisAngle(new T.Vector3(1,0,0),rpy[0]),qy=new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),rpy[1]),qz=new T.Quaternion().setFromAxisAngle(new T.Vector3(0,0,1),rpy[2]);const expectedQ=link.getWorldQuaternion(new T.Quaternion()).multiply(qz.multiply(qy).multiply(qx));return marker.getWorldPosition(new T.Vector3()).distanceTo(expected)<1e-8&&Math.abs(marker.getWorldQuaternion(new T.Quaternion()).dot(expectedQ))>1-1e-8})})()'''
    check(client, alignment, 'center-of-mass spheres follow inertial xyz and rpy')
    inertia_alignment='''(()=>{const T=helperTestThree,v=urdfWorkbench.viewer;v.world.updateWorldMatrix(true,true);const data={base:[1,[.01,.002,-.001,.002,.018,.003,-.001,.003,.022]],arm:[.6,[.01,0,0,0,.01,0,0,0,.01]],slider:[.3,[.01,0,0,0,.01,0,0,0,.01]]};return Object.entries(v.robot.links).every(([name,link])=>{const group=link.children.find(c=>c.userData.markerKind==='inertia'),com=link.children.find(c=>c.userData.markerKind==='com'),box=group?.children.find(c=>c.userData.inertiaBox);if(!box||box.geometry.type!=='BoxGeometry'||box.material.wireframe||!box.material.transparent)return false;const [mass,expected]=data[name],s=box.scale,diagonal=new T.Matrix3().set(mass*(s.y*s.y+s.z*s.z)/12,0,0,0,mass*(s.x*s.x+s.z*s.z)/12,0,0,0,mass*(s.x*s.x+s.y*s.y)/12),rotation=new T.Matrix3().setFromMatrix4(new T.Matrix4().makeRotationFromQuaternion(box.quaternion)),actual=rotation.clone().multiply(diagonal).multiply(rotation.clone().transpose());return actual.elements.every((value,i)=>Math.abs(value-expected[(i%3)*3+Math.floor(i/3)])<1e-8)&&group.getWorldPosition(new T.Vector3()).distanceTo(com.getWorldPosition(new T.Vector3()))<1e-8&&Math.abs(group.getWorldQuaternion(new T.Quaternion()).dot(com.getWorldQuaternion(new T.Quaternion())))>1-1e-8})})()'''
    check(client,inertia_alignment,'equivalent inertia boxes reproduce the full tensor and respect inertial xyz/rpy')
    check(client, '''(()=>{const markers=[];urdfWorkbench.viewer.robot.traverse(o=>{if(o.userData.centerOfMassMarker)markers.push(o)});return markers.length===3&&markers.every(s=>s.isMesh&&s.geometry.type==='SphereGeometry'&&s.geometry.groups.length===2&&JSON.stringify(s.material.map(m=>m.color.getHex()).sort((a,b)=>a-b))===JSON.stringify([0x161616,0xf4f4f4])&&s.material.every(m=>m.opacity===1&&!m.depthTest))})()''', 'center-of-mass markers are opaque black/white spheres')
    check(client, '''(()=>{const T=helperTestThree;return Object.values(urdfWorkbench.viewer.robot.links).every(link=>{const frame=link.children.find(c=>c.userData.axisKind==='axes');return frame&&Math.abs(frame.getWorldQuaternion(new T.Quaternion()).dot(link.getWorldQuaternion(new T.Quaternion())))>1-1e-8&&JSON.stringify(frame.children.map(m=>m.material.color.getHex()))===JSON.stringify([0xff0000,0x00ff00,0x0000ff])})})()''', 'RGB coordinate frames align with each link frame')
    axis_alignment = '''(()=>{const T=helperTestThree,v=urdfWorkbench.viewer;v.world.updateWorldMatrix(true,true);return Object.values(v.robot.joints).every(joint=>{const glyph=joint.children.find(c=>c.userData.axisKind==='jointAxes'),axis=joint.axis.clone().transformDirection(joint.matrixWorld);return glyph&&new T.Vector3(0,1,0).transformDirection(glyph.matrixWorld).dot(axis)>1-1e-8&&glyph.children.find(c=>c.userData.axisShaft).material.color.getHex()===0xff0000})})()'''
    check(client, axis_alignment, 'red joint arrows align with declared axes and rotated origins')
    check(client, '''(()=>{const v=urdfWorkbench.viewer,rot=v.robot.joints.rotate.children.find(c=>c.userData.axisKind==='jointAxes'),slide=v.robot.joints.slide.children.find(c=>c.userData.axisKind==='jointAxes'),arc=rot.children.find(c=>c.userData.rotationIndicator),tip=rot.children.find(c=>c.userData.rotationArrowhead);return arc?.geometry.type==='TorusGeometry'&&arc.material.color.getHex()===0x00ff00&&tip?.material.color.getHex()===0x00ff00&&arc.geometry.parameters.arc<Math.PI*2&&!slide.children.some(c=>c.userData.rotationIndicator)})()''', 'rotational joints use green arcs; prismatic joints keep straight indicators')
    check(client, '''(()=>{const materials=[];urdfWorkbench.viewer.robot.traverse(o=>{if(o.isURDFVisual)o.traverse(m=>{if(m.isMesh)materials.push(m.material)})});return materials.length===3&&materials.every(m=>m.transparent&&Math.abs(m.opacity-.32)<1e-8&&!m.depthWrite)})()''', 'inspection markers reveal a translucent model shell')
    client.js('urdfWorkbench.viewer.setJointValue("rotate",.7);urdfWorkbench.viewer.setJointValue("slide",.12)')
    rendered_frame(client)
    check(client, alignment+'&&'+axis_alignment+'&&'+inertia_alignment, 'marker centers and directions follow joint motion')
    check(client, '''(()=>{const T=helperTestThree,ray=new T.Raycaster(),helpers=[];ray.setFromCamera(new T.Vector2(0,0),urdfWorkbench.viewer.camera);urdfWorkbench.viewer.robot.traverse(o=>{if(o.userData.markerKind==='com'||o.userData.markerKind==='inertia'||o.userData.axisKind)helpers.push(o)});return ray.intersectObjects(helpers,true).length===0})()''', 'reference helper glyphs cannot intercept link selection')
    client.screenshot(str(output/'reference-helper-alignment.png'))
    for key in ['inertia', 'com', 'axes', 'jointAxes']:
        client.js('document.querySelector('+json.dumps(f'[data-display={key}]')+').click()')
    check(client, '''(()=>{const v=urdfWorkbench.viewer,material=name=>v.robot.links[name].children.find(c=>c.isURDFVisual).children.find(c=>c.isMesh).material;return material('base').opacity===1&&!material('base').transparent&&material('base').depthWrite&&Math.abs(material('arm').opacity-.65)<1e-8&&material('arm').transparent})()''', 'closing all markers restores original opaque and translucent materials')
